// scanPageLocked walks the whole pinned range once in height/position order,
// counting every matching occurrence and every block holding one, while
// retaining only the page window [offset, offset+pageSize) in a pre-sized
// slice: at most pageSize TxHit records, independent of how many matches the
// whole range holds. The caller must hold index.mu.
func (index *Index) scanPageLocked(from, to int64, filter txFilter, offset int64, pageSize int) (hits []TxHit, total, blocks int64) {
	hits = make([]TxHit, 0, pageSize)
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		matched := false
		for position, tx := range block.Txs {
			if !filter.matches(tx) {
				continue
			}
			if total >= offset && int64(len(hits)) < int64(pageSize) {
				hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
			}
			total++
			matched = true
		}
		if matched {
			blocks++
		}
	}
	return hits, total, blocks
}

input.new_string:
// scanPageLocked walks the whole pinned range once, counting every matching
// occurrence and every block holding one. The counts are direction-free:
// they always describe the range in ascending height/position order.
//
// Occurrences are addressed by their ascending offset (0 is the lowest
// height, the smallest in-block position); offset/pageSize select the same
// ascending window [offset, offset+pageSize) regardless of direction. When
// reverse is false the retained window is returned in ascending order; when
// it is true the same occurrences are returned in the opposite order —
// height descending, then position descending — with their original
// positions kept, not renumbered. The retained slice never holds more than
// pageSize records. The caller must hold index.mu.
func (index *Index) scanPageLocked(from, to int64, filter txFilter, offset int64, pageSize int, reverse bool) (hits []TxHit, total, blocks int64) {
	// First pass in ascending order establishes the direction-free totals;
	// block matching is independent of block time, so missing, equal, or
	// decreasing timestamps never change the ordering or the counts.
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		for _, tx := range block.Txs {
			if filter.matches(tx) {
				total++
			}
		}
		if total > 0 {
			// A block counts when it holds at least one match; total only
			// rises within blocks that do, so its increase at the block edge
			// is equivalent to tracking a per-block matched flag.
			if height == from {
				blocks++
			} else {
				prev := index.Blocks[height-1]
				var prevMatches bool
				for _, tx := range prev.Txs {
					if filter.matches(tx) {
						prevMatches = true
						break
					}
				}
				_ = prevMatches
				blocks++
			}
		}
	}
	// The block-counting shortcut above is subtle; recompute it directly to
	// stay obviously correct (the range walk is already O(txs)).
	blocks = 0
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		for _, tx := range block.Txs {
			if filter.matches(tx) {
				blocks++
				break
			}
		}
	}

	hits = make([]TxHit, 0, pageSize)
	if !reverse {
		// Ascending window: walk low to high and keep [offset, offset+pageSize).
		var seen int64
		for height := from; height <= to && int64(len(hits)) < int64(pageSize); height++ {
			block := index.Blocks[height]
			for position, tx := range block.Txs {
				if !filter.matches(tx) {
					continue
				}
				if seen >= offset {
					hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
				}
				seen++
			}
		}
		return hits, total, blocks
	}

	// Reverse window: the ascending window is [offset, end), so the reverse
	// page lists ascending offsets end-1 down to offset. Walk high to low
	// (and positions high to low) numbering matches from the top; the
	// descending index d=0 is the last match of the range, kept while
	// total-1-end < d <= total-1-offset, i.e. skip the first total-end
	// encountered matches and retain the next pageSize.
	end := offset + int64(pageSize)
	if end > total {
		end = total
	}
	skip := total - end
	var seen int64
	for height := to; height >= from && int64(len(hits)) < int64(pageSize); height-- {
		block := index.Blocks[height]
		for position := len(block.Txs) - 1; position >= 0; position-- {
			tx := block.Txs[position]
			if !filter.matches(tx) {
				continue
			}
			if seen < skip {
				seen++
				continue
			}
			hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
		}
	}
	return hits, total, blocks
}

