// continuation cursor when matches remain. total and blocks describe the
// whole pinned range; hits holds only the window [offset, offset+pageSize)
// of the ascending occurrence list, already in the requested direction.
// reqTo is the caller's verbatim To (zero for tip-bound queries). The caller
// must hold index.mu.
func (index *Index) buildPageLocked(reqTo int64, filter txFilter, from, to int64, hits []TxHit, total, blocks, offset int64, pageSize int, reverse bool) TxPage {
