	// which the cursor offset is interpreted against in both directions.
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		matched := false
		for _, tx := range block.Txs {
			if filter.matches(tx) {
				total++
				matched = true
			}
		}
		if matched {
			blocks++
		}
